	sections = {
		{
			title = "Summary",
			text = [=[The Commons is the ward of trade in {link:ironforge}Ironforge{/link}. Here stand the Vault of Ironforge, where the city's wealth and that of its visitors is kept under guard, the great auction hall and the inn of Innkeeper Firebrew. Merchants of every people of the {link:alliance}Alliance{/link} come here, and the ward is loud with bargaining from the first hour to the last. Travelers who have been long on the road come to the inn for a warm hearth and a strong ale before they go on.]=],
		},
	},
