	sections = {
		{
			title = "Summary",
			text = [=[Magni Bronzebeard is King of {link:ironforge}Ironforge{/link} and lord of the Bronzebeard dwarves. He is the eldest of three brothers, and the heaviest crown in Khaz Modan rests on his head. From {link:high-seat}the High Seat{/link} he rules a proud and stubborn people, bargains with a Senate that does not always share his mind, and keeps faith with an {link:alliance}Alliance{/link} that has cost him dearly.]=],
		},
		{
			title = "Significance",
			text = [=[Magni is one of the pillars of the {link:alliance}Alliance{/link}. When the {link:horde}Horde{/link} overran Khaz Modan in the {link:second-war}Second War{/link}, his people did not forget who stood with them, and {link:ironforge}Ironforge{/link} has kept its word to humankind ever since. When the gnomes lost their city, he took them in. When the Alliance calls, his soldiers go. It is Magni's burden that each of those choices has been paid for by his own people.]=],
		},
		{
			title = "Deeds",
			text = [=[• He leads the {link:kingdom-of-ironforge}Kingdom of Ironforge{/link} and holds its seat in the {link:alliance}Alliance{/link}.
