			text = [=[High Explorer Magellas leads the {link:explorers-league}Explorers' League{/link} from the {link:hall-of-explorers}Hall of Explorers{/link}. He is a busy {link:dwarves}dwarf{/link}, and he lets visitors know it. Yet no one in {link:ironforge}Ironforge{/link} is more excited by a real discovery, and when one lands on his table, his dignity goes out of the window.]=],
		},
		{
			title = "Significance",
			text = [=[Under Magellas, the League pursues the question that matters most to it: the proof that the dwarves were shaped from stone by the titans, whom the old records call the Creators. He believes that proof may be within reach.]=],
		},
		{
			title = "Deeds",
			text = [=[• He directs the League's expeditions and rewards those who serve it from the League's vault.
• He studies the miniature {link:lore-keeper-of-norgannon}Discs of Norgannon{/link} brought back from {link:uldaman}Uldaman{/link}.
• He turns the League's eyes toward {link:valley-of-the-watchers}Uldum{/link}, far to the south in {link:tanaris}Tanaris{/link}.]=],
		},
	},
	chapters = {
		{
			key = "the-platinum-discs",
			title = "The Platinum Discs",
			hint = "Bring the League a find from the depths of Uldaman.",
			unlock = {
				{ type = "quest", id = 2279 },
			},
			text = [=[When a copy in miniature of the {link:lore-keeper-of-norgannon}Discs of Norgannon{/link} was laid before him, Magellas asked where it was found, and then asked again, and could not believe the answers. He called it the find of the century. If the discs said what he thought, they would settle the old question of the dwarves' origin once and for all.]=],
		},
		{
			key = "uldum-beckons",
			title = "Uldum Beckons",
			hint = "Follow the discs to the gates of Uldum and report back.",
			unlock = {
				{ type = "quest", id = 2964 },
			},
			text = [=[The discs led to {link:valley-of-the-watchers}the sealed gates of Uldum{/link}, where another watcher of stone spoke of plates that were missing. Magellas agreed with his scholars that the search must wait until they knew where to look. He promised that when the time came, the League would send the same hands back into the field.]=],
		},
	},
	mentions = {
